ALTER TABLE "User" DROP COLUMN IF EXISTS "gameXAPlayerId";
CREATE TABLE IF NOT EXISTS "GscWalletTransaction" ("id" TEXT NOT NULL,"providerTransactionId" TEXT NOT NULL,"userId" TEXT NOT NULL,"memberAccount" TEXT NOT NULL,"action" TEXT NOT NULL,"amount" DECIMAL(18,4) NOT NULL,"currency" TEXT NOT NULL,"productCode" INTEGER,"gameType" TEXT,"gameCode" TEXT,"wagerCode" TEXT,"roundId" TEXT,"beforeBalance" DECIMAL(18,4) NOT NULL,"afterBalance" DECIMAL(18,4) NOT NULL,"payload" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "GscWalletTransaction_pkey" PRIMARY KEY ("id"),CONSTRAINT "GscWalletTransaction_providerTransactionId_key" UNIQUE ("providerTransactionId"),CONSTRAINT "GscWalletTransaction_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE INDEX IF NOT EXISTS "GscWalletTransaction_userId_createdAt_idx" ON "GscWalletTransaction"("userId","createdAt");
CREATE INDEX IF NOT EXISTS "GscWalletTransaction_wagerCode_idx" ON "GscWalletTransaction"("wagerCode");
CREATE TABLE IF NOT EXISTS "GscWager" ("id" TEXT NOT NULL,"wagerCode" TEXT NOT NULL,"userId" TEXT,"memberAccount" TEXT NOT NULL,"currency" TEXT NOT NULL,"productCode" INTEGER,"gameType" TEXT,"gameCode" TEXT,"wagerType" TEXT,"wagerStatus" TEXT NOT NULL,"roundId" TEXT,"betAmount" DECIMAL(18,4) NOT NULL,"validBetAmount" DECIMAL(18,4) NOT NULL,"prizeAmount" DECIMAL(18,4) NOT NULL,"tipAmount" DECIMAL(18,4) NOT NULL DEFAULT 0,"settledAt" TIMESTAMP(3),"providerCreatedAt" TIMESTAMP(3),"payload" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "GscWager_pkey" PRIMARY KEY ("id"),CONSTRAINT "GscWager_wagerCode_key" UNIQUE ("wagerCode"),CONSTRAINT "GscWager_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE INDEX IF NOT EXISTS "GscWager_memberAccount_createdAt_idx" ON "GscWager"("memberAccount","createdAt");
CREATE INDEX IF NOT EXISTS "GscWager_userId_createdAt_idx" ON "GscWager"("userId","createdAt");
